/// The translation of an English display text, if the language has one.
pub fn lookup(lang: &str, en: &str) -> Option<&'static str> {
    let table: &[(&str, &str)] = match lang {
        "es" => ES,
        "fr" => FR,
        "it" => IT,
        "pt" => PT,
        _ => return None,
    };
    table
        .binary_search_by(|(k, _)| (*k).cmp(en))
        .ok()
        .map(|i| table[i].1)
}
